/* Sticker Studio presentation layer. Existing modules own accounts, search, credits and posts. */
(() => {
  'use strict';
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', up:'<path d="m7 17 10-10M7 7h10v10"/>',
    search:'<circle cx="10" cy="10" r="7"/><path d="m16 16 5 5"/>', mall:'<path d="m3 9 2-5h14l2 5M4 9v11h16V9M9 20v-6h6v6M3 9q3 4 6 0 3 4 6 0 3 4 6 0"/>',
    community:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',
    image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 17 5-5 5 5 4-6 4 5"/>',
    mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>', stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',
    lock:'<rect x="4" y="10" width="16" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>', coin:'<circle cx="12" cy="12" r="9"/><path d="M12 7v10"/>', check:'<path d="m5 12 4 4L19 6"/>'
  };
  const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.up}</svg>`;
  const bao = (size=120,mood='idle') => `<button type="button" class="ss-bao ${mood}" style="--bao-size:${size}px" data-studio="boop" aria-label="Say hello to Bao"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ear ear-l" cx="28" cy="28" r="16" fill="#2B1620"/><circle class="ear ear-r" cx="92" cy="28" r="16" fill="#2B1620"/><circle cx="60" cy="66" r="46" fill="white" stroke="#2B1620" stroke-width="4"/><ellipse cx="42" cy="62" rx="11" ry="13" fill="#2B1620" transform="rotate(-20 42 62)"/><ellipse cx="78" cy="62" rx="11" ry="13" fill="#2B1620" transform="rotate(20 78 62)"/><g class="eyes-open"><g class="eye"><circle cx="43" cy="61" r="5" fill="white"/><circle class="pupil" cx="43" cy="61" r="2.6" fill="#2B1620"/></g><g class="eye"><circle cx="77" cy="61" r="5" fill="white"/><circle class="pupil" cx="77" cy="61" r="2.6" fill="#2B1620"/></g></g><g class="eyes-happy" fill="none" stroke="white" stroke-width="3" stroke-linecap="round"><path d="M37 63Q43 56 49 63M71 63Q77 56 83 63"/></g><ellipse cx="60" cy="78" rx="5" ry="3.5" fill="#2B1620"/><path d="M54 85Q60 90 66 85" fill="none" stroke="#2B1620" stroke-width="3" stroke-linecap="round"/><ellipse cx="33" cy="80" rx="6" ry="3.5" fill="#F4B6C8"/><ellipse cx="87" cy="80" rx="6" ry="3.5" fill="#F4B6C8"/></svg></button>`;
  const guide = (text,size=100) => `<div class="ss-guide">${bao(size)}<div class="ss-bubble"><small>BAO SAYS</small><span data-bao-says>${esc(text)}</span></div></div>`;
  const subnav = active => `<nav class="ss-subnav" aria-label="Discover sections"><div class="ss-segment"><span class="ss-slider" aria-hidden="true"></span>${[['home','Home','discover'],['ask','Ask Bao','discover/ask'],['mall','Mall','discover/mall'],['community','Community','discover/community']].map(([id,label,route])=>`<a href="#${route}" ${id===active?'aria-current="page"':''}>${label}</a>`).join('')}</div></nav>`;
  const home = () => `${subnav('home')}<section class="ss-home"><div class="ss-hero"><div><p class="ss-eyebrow">${window.TBWAccount?.profile?.name?`Hey ${esc(window.TBWAccount.profile.name.split(' ')[0])} · `:''}DISCOVER</p><h1>Describe a garment<br><span class="ss-highlight">you are looking for</span></h1><p class="ss-lead">A screenshot, a vibe, a little curiosity. Start anywhere.</p></div>${guide('Hi, I’m Bao! Let’s find your next favourite.',116)}</div><div class="ss-tiles"><a href="#discover/ask" class="ss-tile ss-pink"><div class="ss-tile-head"><span class="ss-icon">${icon('search')}</span><span class="ss-round">${icon('up')}</span></div><div><h2>Ask Bao</h2><p>Seen something you love?<br>Let’s find the pieces.</p></div><div class="ss-fake-input">${icon('image')}<span data-example-prompt>Linen shirt under my budget…</span><span class="ss-caret" aria-hidden="true"></span></div><span class="ss-tag">Your style detective</span></a><a href="#discover/mall" class="ss-tile ss-sand"><div class="ss-tile-head"><span class="ss-icon">${icon('mall')}</span><span class="ss-round">${icon('up')}</span></div><div><h2>The Mall</h2><p>100 stores. Nine districts.<br>A whole world of your kind of style.</p></div><div class="ss-mini-map" aria-hidden="true">${Array.from({length:9},(_,i)=>`<span style="--i:${i}"></span>`).join('')}</div><span class="ss-tag">No wrong turns</span></a><a href="#discover/community" class="ss-tile ss-sage"><div class="ss-tile-head"><span class="ss-icon">${icon('community')}</span><span class="ss-round">${icon('up')}</span></div><div><h2>Community</h2><p>Some pieces take a search party.<br>Find it, together.</p></div><div class="ss-crew" aria-hidden="true"><span>A</span><span>R</span><span>M</span><span>YOU</span></div><span class="ss-tag">Good finds, shared</span></a></div><div class="ss-chat-heading"><h2>Your chats</h2><span>Every good find starts somewhere.</span></div><div id="ss-home-chats">${window.DiscoverConversation?.homeChats()||''}</div><p class="ss-footer">A little less scrolling. A little more you.</p></section>`;
  const welcome = ({google,preview,busy,error}) => `<div class="ss-welcome"><header class="ss-welcome-top"><a class="ss-wordmark" href="#welcome">${document.querySelector?.('.topbar .brand-mark')?.outerHTML||icon('mall')}<span>The Wardrobe<b>OS</b></span></a><button type="button" class="ss-button ss-soft" data-ob="free">Skip, just browse ${icon('arrow')}</button></header><div class="ss-welcome-grid"><div class="ss-welcome-copy"><span class="ss-tag ss-pink">YOUR STYLE, YOUR LITTLE WORLD</span><h1>Your style,<br><span class="ss-connected">connected.<svg viewBox="0 0 300 18" preserveAspectRatio="none" aria-hidden="true"><path d="M4 12C60 2 110 18 160 8S260 4 296 10" fill="none" stroke="#E85A96" stroke-width="6" stroke-linecap="round"/></svg></span></h1><p class="ss-lead">Find the looks you love, style what you own, and keep your whole wardrobe in one place — with Bao doing the digging.</p><div class="ss-welcome-actions">${google?'<a class="ss-button ss-primary" href="/api/auth/google">Continue with Google</a>':preview?`<button type="button" class="ss-button ss-primary" data-ob="preview" ${busy?'disabled':''}>Set up my profile ${icon('arrow')}</button>`:''}<button type="button" class="ss-button ss-ghost" data-ob="free">Explore freely</button></div><p class="ss-privacy">${icon('lock')}${google?'Your profile and saved chats stay connected to your account.':'Explore now. Set up a preview profile to save your chats.'}</p>${error?`<p role="alert">${esc(error)}</p>`:''}<div class="ss-mini-features">${[['image','Snap it','Drop a screenshot or describe it'],['mall','Shop the mall','100 stores across 9 districts'],['community','Ask the crew','Good taste loves company']].map(([ic,title,text],i)=>`<div data-tilt class="ss-mini"><span class="ss-icon ss-${['pink','sand','sage'][i]}">${icon(ic)}</span><strong>${title}</strong><p>${text}</p></div>`).join('')}</div></div><div class="ss-collage"><div class="ss-disc"></div><div class="ss-orbit"></div><div class="ss-hero-bao">${bao(245)}</div><span class="ss-tag ss-float-stores">100 stores · 1 mall</span><div class="ss-screenshot"><img src="assets/cream.png" alt="Cream shirt style reference"><span>A little inspiration<br><b>A whole new possibility.</b></span></div><div class="ss-collage-bubble">${guide('Drop me a screenshot. I love a good mystery.',0)}</div><span class="ss-tag ss-float-note">Made for your kind of style</span></div></div></div>`;
  const lookPhotos = new Map();
  const photoQuery = look => `${look.who.replace('Don Draper','Jon Hamm').replace('Harvey Specter','Gabriel Macht')} ${look.label}`;
  const photoMarkup = (look,photo) => photo?.image ? `<img src="${esc(photo.image)}" alt="${esc(look.who.split(' · ')[0]+' avatar')}" loading="lazy" referrerpolicy="no-referrer">` : `<span class="ss-photo-status" title="${photo?.done?'Photo unavailable':'Finding a web photo…'}">${esc(look.who.split(' · ')[0].split(/\s+/).slice(0,2).map(word=>word[0]).join(''))}</span>`;
  const lookArt = look => {
    const q=photoQuery(look);
    if(!lookPhotos.has(q)&&typeof window.fetch==='function'){
      lookPhotos.set(q,{});
      window.fetch('/api/discover/look-photo?q='+encodeURIComponent(q)).then(r=>{if(!r.ok)throw new Error('Photo unavailable');return r.json();}).then(photo=>{
        lookPhotos.set(q,{...photo,done:true});
        document.querySelectorAll('[data-look-photo]').forEach(el=>{if(el.dataset.lookPhoto!==q)return;el.innerHTML=photoMarkup(look,{...photo,done:true});const source=el.closest('.ss-look-card')?.querySelector('.ss-photo-source');if(source&&photo.source){source.href=photo.source;source.textContent='Avatar photo ↗';source.hidden=false;}});
      }).catch(()=>{lookPhotos.set(q,{done:true});document.querySelectorAll('[data-look-photo]').forEach(el=>{if(el.dataset.lookPhoto===q)el.innerHTML=photoMarkup(look,{done:true});});});
    }
    return `<span class="ss-look-art" data-look-photo="${esc(q)}">${photoMarkup(look,lookPhotos.get(q))}</span>`;
  };
  const lookSource = look => {const photo=lookPhotos.get(photoQuery(look));return `<a class="ss-photo-source" ${photo?.source?`href="${esc(photo.source)}"`:'hidden'} target="_blank" rel="noopener noreferrer">${'Avatar photo ↗'}</a>`;};
  let referenceTimer,referenceVersion=0;
  document.addEventListener('input',event=>{
    if(event.target.id!=='dc-text')return;
    clearTimeout(referenceTimer);const q=event.target.value.trim(),version=++referenceVersion;
    const host=document.getElementById('ss-prompt-photo');if(!host)return;host.innerHTML='';
    if(q.length<8)return;
    referenceTimer=setTimeout(async()=>{
      host.textContent='Finding a web reference…';
      try{const r=await window.fetch('/api/discover/look-photo?q='+encodeURIComponent(q.slice(0,300))),photo=await r.json();if(version!==referenceVersion||!host.isConnected)return;
        host.innerHTML=photo.image?`<a href="${esc(photo.source)}" target="_blank" rel="noopener noreferrer"><img src="${esc(photo.image)}" alt="Web reference for ${esc(q)}" referrerpolicy="no-referrer"><span>${photo.portrait?'Person avatar':'Photo thumbnail'} · Source ↗</span></a>`:'No matching web photo found. You can still search this prompt.';
      }catch{if(version===referenceVersion)host.textContent='Web photo unavailable. You can still search this prompt.';}
    },900);
  });
  const communityIntro = () => `<div class="ss-community-guide">${guide('Some pieces take a search party. Ask the crew.',108)}</div>`;
  const skeletons = () => `<div class="ss-skeletons" aria-hidden="true">${Array.from({length:4},()=>'<div><span></span><i></i><i></i></div>').join('')}</div>`;
  const promptChips=()=>`<div class="ss-prompts">${['Find a linen shirt','Something under ₹2,000','Help me find this look'].map(text=>`<button type="button" data-conversation="prompt" data-value="${esc(text)}">${esc(text)}</button>`).join('')}</div>`;
  const modelModes=(models,current,busy)=>`<div class="ss-segment ss-model-modes" aria-label="Search mode"><span class="ss-slider" aria-hidden="true"></span>${models.map(m=>`<button type="button" data-conversation="pick-model" data-id="${esc(m.id)}" aria-pressed="${m.id===current.id}" ${busy?'disabled':''} title="${esc(m.note)} · ${m.credits} credits">${esc(m.label==='Lite'?'Quick':m.label)}<small>${m.credits} credits</small></button>`).join('')}</div>`;
  const invalid=()=>{const composer=document.querySelector('.dc-composer');if(composer){composer.classList.remove('ss-shake');void composer.offsetWidth;composer.classList.add('ss-shake');}say(document.querySelector('.ss-guide'),'Give me a hint: a few words or a screenshot.');announce('Add a description or screenshot to start.');};
  window.StickerStudio={icon,bao,guide,subnav,home,welcome,lookArt,lookSource,communityIntro,skeletons,promptChips,modelModes,invalid};
  const reduced = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
  const announce = text => {const el=document.getElementById('toast');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(announce.timer);announce.timer=setTimeout(()=>el.classList.remove('show'),3400);};
  const say = (host,text) => {const el=host?.querySelector('[data-bao-says]');if(!el)return;clearInterval(el._typing);if(reduced()){el.textContent=text;return;}let n=0;el.textContent='';el._typing=setInterval(()=>{el.textContent=text.slice(0,++n);if(n>=text.length)clearInterval(el._typing);},18);};
  function burst(el){if(reduced())return;const r=el.getBoundingClientRect();const fx=document.createElement('div');fx.className='ss-fx';fx.setAttribute('aria-hidden','true');document.body.append(fx);for(let i=0;i<12;i++){const p=document.createElement('span'),a=Math.PI*2*i/12;p.style.cssText=`left:${r.left+r.width/2}px;top:${r.top+r.height/2}px;--dx:${Math.cos(a)*85}px;--dy:${Math.sin(a)*85-30}px;background:${['#8E1B4D','#F2C14E','#C5C3A8','#EBBDD0'][i%4]}`;fx.append(p);}setTimeout(()=>fx.remove(),1000);}
  function indicators(){document.querySelectorAll('.ss-segment').forEach(seg=>{const on=seg.querySelector('[aria-current="page"],[aria-pressed="true"]'),ind=seg.querySelector('.ss-slider');if(on&&ind){ind.style.width=on.offsetWidth+'px';ind.style.transform=`translateX(${on.offsetLeft}px)`;}});}
  function decorate(){const main=document.getElementById('main');if(main){main.dataset.studio=location.hash.startsWith('#discover')||!location.hash?'true':'false';}indicators();const balance=window.DiscoverConversation?.balance?.();const nav=document.querySelector('.topbar');if(nav){let pill=nav.querySelector('.ss-coins');if(!pill){pill=document.createElement('a');pill.className='ss-coins';pill.href='#profile';pill.setAttribute('aria-label','View credits in your profile');nav.insertBefore(pill,nav.querySelector('.preview-label'));}const text=balance==null?'Credits':String(balance);if(pill.dataset.balance!==text){pill.innerHTML=icon('coin')+`<span>${esc(text)}</span>`;pill.dataset.balance=text;}}
  }
  document.addEventListener('click',event=>{const b=event.target.closest('[data-studio]');if(b?.dataset.studio==='boop'){b.classList.add('happy');say(b.closest('.ss-guide')||document.querySelector('.ss-collage-bubble'),'Boop. Ready when you are!');burst(b);setTimeout(()=>b.classList.remove('happy'),1500);}
    const look=event.target.closest('[data-conversation="shuffle"]');if(look)document.querySelectorAll('.dc-examples>button,.ss-look-card').forEach((el,i)=>{el.style.animationDelay=i*80+'ms';el.classList.add('ss-flip');});
    const choice=event.target.closest('[data-mall="category"]');if(choice)burst(choice);
    const send=event.target.closest('.dc-send');if(send)burst(send);
  });
  document.addEventListener('focusin',event=>{if(event.target.id==='dc-text'){document.querySelector('.ss-bao')?.classList.add('perk');say(document.querySelector('.ss-guide'),'Go on, I’m all ears.');}});
  document.addEventListener('focusout',event=>{if(event.target.id==='dc-text')document.querySelector('.ss-bao')?.classList.remove('perk');});
  let frame=0,point=null;
  document.addEventListener('pointermove',event=>{if(reduced())return;point={x:event.clientX,y:event.clientY,target:event.target};if(frame)return;frame=requestAnimationFrame(()=>{frame=0;document.querySelectorAll('.ss-bao').forEach(b=>{const r=b.getBoundingClientRect(),dx=point.x-r.left-r.width/2,dy=point.y-r.top-r.height*.52,d=Math.hypot(dx,dy)||1,k=Math.min(1,d/300)*2.2;b.querySelectorAll('.pupil').forEach(p=>p.setAttribute('transform',`translate(${dx/d*k} ${dy/d*k})`));});const tile=point.target.closest('[data-tilt],.ss-tile');if(tile&&matchMedia('(hover:hover)').matches){const r=tile.getBoundingClientRect();tile.style.setProperty('--rx',-(point.y-r.top-r.height/2)/r.height*5+'deg');tile.style.setProperty('--ry',(point.x-r.left-r.width/2)/r.width*5+'deg');}});},{passive:true});
  document.addEventListener('pointerout',event=>{const tile=event.target.closest('[data-tilt],.ss-tile');if(tile&&!tile.contains(event.relatedTarget)){tile.style.removeProperty('--rx');tile.style.removeProperty('--ry');}});
  setInterval(()=>{if(reduced()||document.hidden)return;document.querySelectorAll('.ss-bao:not(.happy)').forEach(b=>{b.classList.add('blink');setTimeout(()=>b.classList.remove('blink'),140);});},3700);
  const tips=['Hi, I’m Bao! Start anywhere.','Try dropping a screenshot.','Trending looks are one tap away.','Some pieces take a search party.'];let tip=0;
  setInterval(()=>{if(document.hidden||reduced())return;const host=document.querySelector('.ss-home .ss-guide');if(host)say(host,tips[++tip%tips.length]);},5200);
  const prompts=['Linen shirt under my budget…','An oversized tee like this pic…','A little something for the weekend…'];let prompt=0;
  setInterval(()=>{if(document.hidden||reduced())return;const el=document.querySelector('[data-example-prompt]');if(!el)return;const text=prompts[++prompt%prompts.length];let i=0;clearInterval(el._typing);el._typing=setInterval(()=>{el.textContent=text.slice(0,++i);if(i>=text.length)clearInterval(el._typing);},55);},4500);
  window.addEventListener('resize',indicators);
  document.fonts.ready.then(indicators);
  window.addEventListener('sticker-data',()=>{const el=document.getElementById('ss-home-chats');if(el)el.innerHTML=window.DiscoverConversation.homeChats();decorate();});
  window.addEventListener('hashchange',()=>requestAnimationFrame(decorate));
  document.addEventListener('DOMContentLoaded',()=>{new MutationObserver(()=>requestAnimationFrame(decorate)).observe(document.getElementById('main'),{childList:true,subtree:true});decorate();});
})();
